+                let t = i as f64 / 4000.0;
+                let u = 1.0 - t;
+                let (w1, w2, w3) = (3.0 * u * u * t, 3.0 * u * t * t, t * t * t);
+                let x = w1 * c[0] + w2 * c[2] + w3 * c[4];
