+                // The viewBox starts at (-10, -10) and is 120 high: x moves by 10, y flips to 110 - y.
+                gap(x + 10.0, 110.0 - y)
+            })
+            .fold(0.0, f64::max);
+        assert!(worst <= svg::CHORD_TOLERANCE_MM, "{d}: {worst} mm from the curve");
+    }
+}

